CREATE TABLE users(id text PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,role text NOT NULL CHECK(role IN('admin','operator','viewer')),password_hash text NOT NULL);
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE applications(id text PRIMARY KEY,name text NOT NULL,description text NOT NULL DEFAULT '',environment text NOT NULL DEFAULT 'development');
CREATE TABLE investigations(id text PRIMARY KEY,application_id text NOT NULL REFERENCES applications(id),title text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches(id text PRIMARY KEY,investigation_id text NOT NULL REFERENCES investigations(id),parent_id text REFERENCES branches(id),title text NOT NULL,model_id text NOT NULL DEFAULT '',revision bigint NOT NULL DEFAULT 0);
CREATE TABLE context_revisions(branch_id text NOT NULL REFERENCES branches(id),revision bigint NOT NULL,messages jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(branch_id,revision));
CREATE TABLE runs(id text PRIMARY KEY,branch_id text NOT NULL REFERENCES branches(id),request_id text NOT NULL,request_hash text NOT NULL,status text NOT NULL CHECK(status IN('queued','running','completed','failed','cancelled')),model_id text NOT NULL,attempt integer NOT NULL DEFAULT 0,error text NOT NULL DEFAULT '',input jsonb NOT NULL,lease_token text,lease_until timestamptz,cancel_requested boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(branch_id,request_id));
CREATE UNIQUE INDEX one_active_run ON runs(branch_id) WHERE status IN('queued','running');
CREATE TABLE attempts(id text PRIMARY KEY,run_id text NOT NULL REFERENCES runs(id),number integer NOT NULL,status text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,error text NOT NULL DEFAULT '');
CREATE TABLE evidence(id text PRIMARY KEY,branch_id text NOT NULL REFERENCES branches(id),run_id text NOT NULL REFERENCES runs(id),kind text NOT NULL,title text NOT NULL,content text NOT NULL,source text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events(seq bigserial PRIMARY KEY,investigation_id text NOT NULL REFERENCES investigations(id),branch_id text REFERENCES branches(id),type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_replay ON events(investigation_id,seq);
CREATE TABLE merge_previews(id text PRIMARY KEY,source_branch_id text NOT NULL REFERENCES branches(id),target_branch_id text NOT NULL REFERENCES branches(id),source_revision bigint NOT NULL,target_revision bigint NOT NULL,additions jsonb NOT NULL,used boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE layouts(user_id text NOT NULL REFERENCES users(id),investigation_id text NOT NULL REFERENCES investigations(id),layout jsonb NOT NULL,PRIMARY KEY(user_id,investigation_id));
